+export function formatShippingLabel(order: Order): string {
+  // order.customer.address can be null or undefined for digital orders
+  return order.customer.address.street.toUpperCase();
+}

--- a/src/services/orders.ts
+++ b/src/services/orders.ts
@@ -40,4 +40,9 @@
+export async function fetchOrderDetails(orders: Order[]) {
+  const results = [];
+  for (const order of orders) {
+    const items = await db.items.find({ orderId: order.id });
+    results.push({ ...order, items });
+  }
+  return results;
+}

